package org.openforis.collect.earth.app.service;

import java.util.concurrent.atomic.AtomicBoolean;

import org.openforis.collect.earth.app.desktop.EarthApp;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

/**
 * Restarts Collect Earth, from the pages, after a setting only a new server reads changed or another project was
 * loaded: what the Swing properties dialog did (ApplyOptionChangesListener.restartEarth). The checksums of the
 * generated files are cleared first, so the new process regenerates the KML, then EarthApp.restart stops the server,
 * starts a new process with the same command line and exits this one.
 * <p>
 * As QuitService, run() returns at once and the restart goes on in a thread of its own, so the HTTP request that
 * asked for it is answered first. A second call while restarting does nothing.
 */
@Service
public class RestartService implements Runnable {

	private final Logger logger = LoggerFactory.getLogger(RestartService.class);

	private final Runnable prepare;
	private final Runnable restart;
	private final AtomicBoolean stopping;

	@Autowired
	public RestartService(LocalPropertiesService properties) {
		this(properties::nullifyChecksumValues, EarthApp::restart, QuitService.STOPPING);
	}

	/** For the tests, which cannot let the process restart. */
	RestartService(Runnable prepare, Runnable restart) {
		this(prepare, restart, new AtomicBoolean());
	}

	RestartService(Runnable prepare, Runnable restart, AtomicBoolean stopping) {
		this.prepare = prepare;
		this.restart = restart;
		this.stopping = stopping;
	}

	@Override
	public void run() {
		if (!stopping.compareAndSet(false, true)) {
			return;
		}
		new Thread(() -> {
			try {
				prepare.run();
			} catch (RuntimeException e) {
				// The KML is then regenerated by its own checks; the restart matters more
				logger.error("Error preparing the restart of Collect Earth", e);
			}
			restart.run();
		}, "Restarting Collect Earth").start();
	}
}
